14	
15	interface Props {
16	  avatarUrl: string | null | undefined;
17	  displayName: string | undefined;
18	  height?: number;
19	  width?: number;
20	  borderRadius?: number;
21	  onPress?: (uri: string) => void;
22	}
23	
24	export const UserImage: FC<Props> = ({
25	  avatarUrl,
26	  displayName,
27	  height = 32,
28	  width = 32,
29	  borderRadius = 48,
30	  onPress,
31	}) => {
32	  const [uri, setUri] = useState<string | null>(null);
33	  const uriRef = useRef<string | null>(null);
34	  const textSize = () => {
35	    if (height < 20) return TextSize.xtiny;
36	    if (height < 28) return TextSize.tiny;
37	    if (height < 32) return TextSize.small;
38	    if (height < 40) return TextSize.base;
39	    if (height < 48) return TextSize.medium;
40	    if (height < 56) return TextSize.large;
41	
42	    return TextSize.xlarge;
43	  };
44	
45	  const resolveAvatar = useCallback(async () => {
46	    if (!avatarUrl) return;
47	
48	    try {
49	      if (await isCached(avatarUrl)) {
50	        const cached = getCachedImagePathByURL(avatarUrl);
51	        uriRef.current = cached;
52	        setUri(cached);
53	        return;
54	      }
55	      const url = await fetchMedia({
56	        url: avatarUrl,
57	        width,
58	        height,
59	        serverUrl:
60	          MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
61	      });
62	      if (!url) return;
63	      await cacheImageWithKey(avatarUrl, url);
64	      if (await isCached(avatarUrl)) {
65	        const cached = getCachedImagePathByURL(avatarUrl);
66	        uriRef.current = cached;
67	        setUri(cached);
68	      }
69	    } catch (e) {
70	      console.log(e);
71	    }
72	  }, [avatarUrl, width, height]);
73	
74	  useEffect(() => {
75	    uriRef.current = null;
76	    setUri(null);
77	    resolveAvatar();
78	  }, [resolveAvatar]);
79	
80	  // Retry on foreground if the initial fetch failed
81	  useEffect(() => {
82	    const subscription = AppState.addEventListener("change", (state) => {
83	      if (state === "active" && !uriRef.current && avatarUrl) {
84	        resolveAvatar();
85	      }
86	    });
87	    return () => subscription.remove();
88	  }, [avatarUrl, resolveAvatar]);
89	
90	  if (uri) {
91	    const image = (
92	      <Image
93	        source={{ uri }}
94	        width={width}
95	        height={height}
96	        style={{
97	          width,
98	          height,
99	          borderRadius,
100	          borderWidth: 2,
101	          borderColor: Colors.white20,
102	        }}
103	      />
104	    );
105	
106	    if (onPress) {
107	      return (
108	        <Button.Wrapper onPress={() => onPress(uri)}>{image}</Button.Wrapper>
109	      );
110	    }
111	
112	    return image;
113	  }
114	
115	  return (
116	    <Block
117	      width={width}
118	      height={height}
119	      border={{
120	        borderWidth: 1,
121	        borderColor: Colors.white20,
122	        borderRadius,
123	      }}
124	      background={Colors.white20}
125	      align="center"
126	      justify="center"
127	    >
128	      <Text size={textSize()} color={Colors.white50}>
129	        {displayName?.charAt(0).toUpperCase()}
130	      </Text>
131	    </Block>
132	  );
133	};
