 * Uses fs.cp() instead of an HTTP download, so it works with file:// paths.
 */
export async function cacheFileFromLocalPath(
  cacheKey: string,
  localFilePath: string,
): Promise<void> {
  const sourcePath = localFilePath.replace("file://", "");
  const destPath = getStoragePathByUrl(cacheKey);

  try {
    if (!CacheDirReady) {
      const dirExists = await ReactNativeBlobUtil.fs.exists(CacheDir);
      if (!dirExists) await ReactNativeBlobUtil.fs.mkdir(CacheDir);
      CacheDirReady = true;
