      if (stat && stat.size > 0) return;
      await ReactNativeBlobUtil.fs.unlink(destPath);
    }

    await ReactNativeBlobUtil.fs.cp(sourcePath, destPath);
  } catch (error) {
    console.warn(`Failed to cache file from ${localFilePath}:`, error);
