import { Block, Text, useAnimateParallel } from "@prototyp/skeletor";
import { useAtom, useAtomValue } from "jotai";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { fetchMedia } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { type FC, useCallback, useEffect, useMemo, useState } from "react";
import {
  Dimensions,
  Modal,
  TouchableWithoutFeedback,
} from "react-native";
import Video, { type OnLoadData } from "react-native-video";
import { Colors } from "shared/styles";
import { Button } from "../button";
import { Loading } from "../loading";

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");

export const VideoViewerModal: FC = () => {
  const [videoViewerUri, setVideoViewerUri] = useAtom(
    TimelineAtoms.videoViewerUri,
  );
  const [videoViewerContent, setVideoViewerContent] = useAtom(
    TimelineAtoms.videoViewerContent,
  );
  const [downloadedUri, setDownloadedUri] = useState<string | null>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [naturalSize, setNaturalSize] = useState<{ width: number; height: number } | null>(null);

  const videoUri = videoViewerUri ?? downloadedUri;
  const visible = !!videoViewerUri || !!videoViewerContent;

  const videoSize = useMemo(() => {
    if (!naturalSize) return { width: SCREEN_WIDTH, height: SCREEN_HEIGHT };
    const scale = Math.min(SCREEN_WIDTH / naturalSize.width, SCREEN_HEIGHT / naturalSize.height);
    return {
      width: Math.round(naturalSize.width * scale),
      height: Math.round(naturalSize.height * scale),
    };
  }, [naturalSize]);

  const controlsAnimation = useAnimateParallel(
    { translateY: [-120, 0], opacity: [0, 1] },
    { duration: 280 },
  );

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  useEffect(() => {
    if (!videoViewerContent) return;
    setIsDownloading(true);
    setHasError(false);
    fetchMedia({
      serverUrl: MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
      mediaSource: videoViewerContent.mediaSource,
      mimeType: videoViewerContent.mimeType,
    })
      .then((uri) => {
        if (uri) setDownloadedUri(uri);
        else setHasError(true);
      })
      .catch(() => setHasError(true))
      .finally(() => setIsDownloading(false));
  }, [videoViewerContent]);

  const onClose = useCallback(() => {
    setVideoViewerUri(null);
    setVideoViewerContent(null);
    setDownloadedUri(null);
    setHasError(false);
    setIsLoading(false);
    setIsDownloading(false);
    setShowControls(true);
    setNaturalSize(null);
  }, [setVideoViewerUri, setVideoViewerContent]);

  const handleVideoLoad = useCallback((data: OnLoadData) => {
    setIsLoading(false);
    setHasError(false);
    setNaturalSize({ width: data.naturalSize.width, height: data.naturalSize.height });
  }, []);

  const handleVideoError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleLoadStart = useCallback(() => {
    setIsLoading(true);
    setHasError(false);
  }, []);

  const handleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleRetry = useCallback(() => {
    if (!videoViewerContent) return;
    setHasError(false);
    setDownloadedUri(null);
    setIsDownloading(true);
    fetchMedia({
      serverUrl: MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
      mediaSource: videoViewerContent.mediaSource,
      mimeType: videoViewerContent.mimeType,
    })
      .then((uri) => {
        if (uri) setDownloadedUri(uri);
        else setHasError(true);
      })
      .catch(() => setHasError(true))
      .finally(() => setIsDownloading(false));
  }, [videoViewerContent]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      animationType="fade"
      statusBarTranslucent
      transparent
      onRequestClose={onClose}
    >
      <Block background={Colors.black} flex={1} justify="center" align="center">
        <Block
          absolute
          offsets={{ top: 0, left: 0, right: 0 }}
          zIndex={10}
          paddings={[56, 20, 16, 20]}
          align="flex-end"
          background={Colors.primary}
          animations={controlsAnimation.animations}
          pointerEvents={showControls ? "auto" : "none"}
        >
          <Button.Wrapper onPress={onClose}>
            <Text size={17} font="InstrumentSans-Semibold" color={Colors.white}>
              Close
            </Text>
          </Button.Wrapper>
        </Block>

        <Block width={videoSize.width} height={videoSize.height}>
          {(isDownloading || (isLoading && !hasError)) && (
            <Block
              absolute
              width={videoSize.width}
              height={videoSize.height}
              align="center"
              justify="center"
              zIndex={5}
              background={Colors.black70}
            >
              <Loading isFullScreen={false} />
            </Block>
          )}

          {hasError ? (
            <Block
              width={videoSize.width}
              height={videoSize.height}
              align="center"
              justify="center"
            >
              <Text color={Colors.white}>Failed to load video</Text>
              <Button.Wrapper onPress={handleRetry}>
                <Text size={14} color={Colors.white}>
                  Tap to retry
                </Text>
              </Button.Wrapper>
            </Block>
          ) : videoUri ? (
            <TouchableWithoutFeedback onPress={handleTap}>
              <Video
                source={{ uri: videoUri }}
                style={{ width: videoSize.width, height: videoSize.height }}
                resizeMode="contain"
                controls
                paused={false}
                onLoad={handleVideoLoad}
                onError={handleVideoError}
                onLoadStart={handleLoadStart}
              />
            </TouchableWithoutFeedback>
          ) : null}
        </Block>
      </Block>
    </Modal>
  );
};

